@import url('https://fonts.googleapis.com/css2?family=inter:wght@400;600;700&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #F2F2F2;
  font-family: "Inter", sans-serif;
}

#ad-300x250 {
  width: 300px;
  height: 250px;
  position: relative;
  overflow: hidden;
  background: #FFED00;
  border: 2px solid #000000;
  font-family: "Inter", sans-serif;
}

/* Background layer */
.bg-layer {
  position: absolute;
  inset: 0;
  background: linear-gradient(145deg, #FFED00 0%, rgba(255, 237, 0, 0.7) 60%, rgba(227, 0, 11, 0.12) 100%);
  z-index: 0;
}

/* Dot grid decoration */
.dot-grid {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, rgba(0,0,0,0.08) 1px, transparent 1px);
  background-size: 12px 12px;
  z-index: 1;
}

/* Header */
.ad-header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 34px;
  background: #E3000B;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  z-index: 10;
}

.brand-logo {
  height: 22px;
  width: auto;
  display: block;
  flex-shrink: 0;
}

.eyebrow {
  font-family: "Inter", sans-serif;
  font-size: 9px;
  font-weight: 700;
  color: #FFFFFF;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
  background: rgba(0,0,0,0.18);
  padding: 2px 6px;
  border-radius: 10px;
}

/* Slideshow */
.slideshow {
  position: absolute;
  top: 34px;
  left: 0;
  width: 300px;
  height: 148px;
  z-index: 5;
  overflow: hidden;
}

.slide {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform: scale(1.04);
  transition: opacity 0.55s cubic-bezier(0.4,0,0.2,1), transform 0.55s cubic-bezier(0.4,0,0.2,1);
  pointer-events: none;
}

.slide.active {
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
}

.product-img {
  width: 100%;
  height: 148px;
  object-fit: cover;
  object-position: center top;
  display: block;
}

.slide-badge {
  position: absolute;
  right: 8px;
  bottom: 8px;
  background: #E3000B;
  color: #FFFFFF;
  font-family: "Inter", sans-serif;
  font-size: 8px;
  font-weight: 700;
  text-align: center;
  line-height: 1.2;
  padding: 3px 7px;
  border-radius: 6px;
  border: 1.5px solid #FFFFFF;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  box-shadow: 0 2px 6px rgba(0,0,0,0.22);
}

/* Slide dots */
.slide-dots {
  position: absolute;
  top: 174px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: center;
  gap: 5px;
  z-index: 10;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1.5px solid #000000;
  background: rgba(0,0,0,0.18);
  cursor: pointer;
  padding: 0;
  transition: background 0.2s, transform 0.2s;
  outline: none;
}

.dot.active {
  background: #E3000B;
  transform: scale(1.25);
  border-color: #E3000B;
}

.dot:hover {
  background: #000000;
  border-color: #000000;
}

/* Copy block */
.copy-block {
  position: absolute;
  top: 186px;
  left: 0;
  right: 0;
  text-align: center;
  z-index: 10;
  padding: 0 12px;
}

.headline {
  font-family: "Inter", sans-serif;
  font-size: 15px;
  font-weight: 800;
  color: #000000;
  line-height: 1.15;
  letter-spacing: -0.01em;
}

.headline em {
  color: #E3000B;
  font-style: normal;
}

.subhead {
  font-family: "Inter", sans-serif;
  font-size: 9px;
  font-weight: 600;
  color: #1A1A1A;
  margin-top: 2px;
  letter-spacing: 0.02em;
}

/* Footer */
.ad-footer {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 42px;
  background: #000000;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px 0 8px;
  z-index: 10;
}

.cta-btn {
  display: inline-flex;
  align-items: center;
  background: #FFED00;
  color: #000000;
  text-decoration: none;
  border-radius: 20px;
  padding: 5px 12px;
  border: 2px solid #000000;
  transition: background 0.18s, transform 0.15s, box-shadow 0.15s;
  box-shadow: 2px 2px 0 rgba(0,0,0,0.35);
  flex-shrink: 0;
}

.cta-btn:hover {
  background: #E3000B;
  color: #FFFFFF;
  transform: translateY(-1px);
  box-shadow: 2px 4px 0 rgba(0,0,0,0.4);
}

.cta-btn:active {
  transform: translateY(0);
  box-shadow: 1px 1px 0 rgba(0,0,0,0.35);
}

.cta-label {
  font-family: "Inter", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}

.ad-footer .body-copy {
  font-family: "Inter", sans-serif;
  font-size: 8px;
  font-weight: 400;
  color: rgba(255,255,255,0.72);
  text-align: right;
  line-height: 1.3;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .slide {
    transition: opacity 0.01s;
  }
  .cta-btn {
    transition: none;
  }
}

